import 'feature_flag_config.dart';

/// Emits the target app's generated `feature_flags.g.dart` source (spec 030
/// FR-005). Pure function: [ResolvedFeatureSet] -> Dart source string.
///
/// The emitted class delegates to `FeatureFlagRuntime` (shipped in the
/// zuraffa package) so gate evaluation, provider swapping, and fail-safe
/// fallbacks are runtime-package behavior, while the per-build feature-set
/// and gate declarations are baked into the generated file (SC-003: O(1)
/// static lookup by default).
String emitRegistry({
  required String className,
  required ResolvedFeatureSet resolved,
  String? flavor,
}) {
  final enabled = resolved.enabledList;
  final enabledLiteral = enabled.isEmpty
      ? ''
      : enabled.map((n) => "'$n'").join(', ');

  final gateNames = resolved.gates.keys.toList()..sort();
  final gateLines = <String>[];
  for (final name in gateNames) {
    final gates = resolved.gates[name]!;
    gateLines.add(
      "    '$name': <String>[${gates.map((g) => "'${g.raw}'").join(', ')}],",
    );
  }

  return '''
// feature_flags.g.dart — GENERATED by `zfa build`${flavor == null ? '' : ' --flavor $flavor'}. DO NOT EDIT.
// Build-time feature registry for this binary.

import 'package:zuraffa/src/feature_flags/feature_flag.dart';
import 'package:zuraffa/src/feature_flags/runtime/feature_flag_provider.dart';

/// Generated feature registry — injectable via your DI setup.
class $className {
  /// Features enabled for THIS build (disabled leave no trace).
  static const List<String> _enabled = <String>[$enabledLiteral];

  /// Gates per feature (colon-delimited runtime conditions).
  static const Map<String, List<String>> _gateSpecs =
      <String, List<String>>{
${gateLines.isEmpty ? '' : gateLines.join('\n')}
  };

  final FeatureFlagRuntime _runtime;

  /// [provider] swaps build-time resolution for a remote /
  /// entitlements-backed implementation (FR-009).
  $className({FeatureFlagProvider? provider})
      : _runtime = FeatureFlagRuntime(
          enabled: _enabled.toSet(),
          gates: _gateSpecs.map(
            (name, specs) => MapEntry(
              name,
              specs.map(FeatureGate.parse).toList(),
            ),
          ),
          provider: provider,
        );

  /// Whether [name] is active for this user/session.
  bool isEnabled(String name) => _runtime.isEnabled(name);

  /// All features enabled for this build.
  List<String> get enabledFeatures => _runtime.enabledFeatures;

  /// Active A/B variant for [feature] (default: a).
  String resolveVariant(String feature) => _runtime.resolveVariant(feature);
}
''';
}
